# -*- coding: utf-8 -*-
"""ch03 R2 ops 3: 3.2合并区+3.3 (行165-339)"""

OPS = [
(169, 173, "谈扣除与加算",
 "谈扣除与加算，先看手边有哪些定额文本可查。本书研究团队把资料库实际收录的定额文本逐一登记成实收全景表（表3-4）——它的价值在一个“实”字：每一行都是完整入库的文本，不是书目传闻；定额员与成本条线拿着它，能快速判断哪个专业条线、哪个层级有现成定额可套。"),
(195, 195, "这张表至少读出三层信息",
 "这张表至少读出三层信息。第一，**定额切分的细密程度远比“房建市政”四个字丰富**：通信电源、文物修缮、土地整理、公路养护、智能建造、轨道交通装备制造，几乎每个专业条线都有自家定额文本，跨专业项目必须逐条核对适用范围，拿房建定额去套文物或养护工程是要出事的。第二，**地方与行业文本的“配套件”意识**：陕西的消耗量定额必跟基价表、台班费用定额和费用规则；甘肃工业厂房定额明确与省计价规则配套执行；深圳的消耗量标准与计价规程、计价费率标准配套——套定额永远连同配套件一起套，缺一件就可能口径错位。第三，**补充定额是体系的新鲜血液**：智能建造这类新技术，正是靠“补充定额+与既有计价定额配套”的路子进入计价体系（P000330），读者判断“新技术能不能计价”，由此有了制度路径。"),
(202, 202, "在建筑与装饰工程中",
 "建筑与装饰工程里，材料形态变更（预拌砂浆替现拌砂浆、商品混凝土替现场拌和）与现场土方开挖条件改变，都躲不开扣除与加算规则（P000302、P000305、P000314）。"),
(243, 243, "  1. 针对通信拆除工程",
 "  1. **通信拆除**：调取《2017版通信工程概预算定额库》拆除系数规定（P000301）——变压器拆除且清理入库，人工系数由1.00**调整为0.70**，核减30%人工费；室外直埋电缆拆除人工系数**确为1.00**，全额结算，电缆拆除申报获支持（P000301）。"),
(244, 244, "  2. 针对砂浆换算",
 "  2. **砂浆换算**：按《房屋建筑与装饰工程消耗量定额》换算规则执行——调换现拌砂浆价格、增计一般技工0.382工日与200L灰浆搅拌机0.167台班、扣除原罐式搅拌机台班（参数明细见3.2.1节）（P000302）；按换算后组合单价重新核算，高套单价与盲目索赔部分被剔除（P000302）。"),
(245, 245, "  3. 针对土方工程",
 "  3. **土方工程**：按浙江地方定额规则，人工挖土方单项定额**乘系数1.25**，加算25%人工费；工程量须**扣除直径800mm以上（本案1.0m）的挖孔桩体积**，未扣部分核减（P000314）。"),
(246, 246, "* **教训/启示**：特殊工程",
 "* **教训/启示**：特殊工程与拆除换算的计价核心是“有据可依、扣加精准”（P000301、P000302、P000314）。项目经理编投标报价或结算送审，手边要常备“拆除系数表”“砂浆换算表”“土方扣减系数清单”三张表（P000301、P000302、P000314）——盲目按100%全额套安装定额，拆除项目会被大幅核减；漏掉承台挖土1.25系数加算，应得的工程价款又白白漏报（P000301、P000314）。"),
(263, 263, "随着我国工程造价",
 "工程造价体系改革向纵深推进，住建部《关于做好工程造价改革创新工作计划方案工作的通知》（建办标〔2020〕38号文）给出总体路线图：取消最高投标限价按定额计价的相关规定，逐渐终止发布预算定额，促进人材机价格进入社会化大调节，全面与国际通行计价惯例接轨（P000315、P000318）。甘肃省住建厅等地方主管部门发布工业厂房预算定额等标准时，也把深化造价改革、定额动态化管理写为推动高质量发展与规范计价行为的核心举措（P000315）。政府统一发布法定预算定额、发承包双方被动套用的旧模式，正在加速退场（P000317、P000318）。"),
(269, 269, "工程建设定额不是一本",
 "这个家族不是一本孤立手册。行业教学口径讲得清楚：施工定额服务施工管理与进度计划，反映施工单位先进水平；预算定额是有基价的定额；概算定额又称扩大结构定额，规定完成单位扩大分项工程或结构构件所必须消耗的人工、材料、机械台班数量标准，以预算定额为基础；概算指标以整个建筑物或构筑物为对象，按“m2”“m3”或“座”计量；投资估算指标则供编制项目建议书、可行性研究报告等前期投资估算，也可作固定资产长远规划投资额的参考[来源: P000323]。"),
(271, 271, "其中与日常组价",
 "日常组价关系最密的预算定额，定义有四要素：适用条件是“正常施工条件”，质量基准是“合格的分项工程或结构构件”，采用标准计量单位保证造价可比，消耗构成覆盖人工、材料、施工机械台班三大生产要素（P000320）。它与概算定额的分界同样清晰：预算定额在基础定额之上综合项目、按工程分部分项划分、以单一工程项目为单位计算，一般是编施工图预算或甲乙双方结算的依据；概算定额再综合扩大、按扩大后工程项目为单位计算，一般供初步设计概算或投资包干使用——前者项目划分细、工程内容单一，后者项目划分粗、内容更多[来源: P000334, P000335]。"),
(286, 286, "关于",
 "关于“水平基准”再补一层体系咬合：预算定额按社会平均水平编制，深层原因是它必须反映大多数企业在正常施工条件下的平均消耗，保证多数企业努力可达；施工定额敢用先进水平，因为它只服务企业内部管理、不对外计价（P000322）。两者还有“涵盖与放大”的关系：预算定额涵盖更多工序和辅助工作，消耗量标准较施工定额更高（P000312）；它以分部分项工程为对象编制，包含劳动定额、材料定额、机械台班定额三大构成要素，带社会平均水平、经授权部门批准发布的法定性、涵盖全部施工过程消耗的综合性三个典型特征（P000312）。"),
(290, 290, "按",
 "按“谁组织编制、谁审批颁发”，预算定额分三层落地，三层权限的完整对应关系与3.3.4节流程末端所列一致，此处不重复列账（P000313）。这一定义体系里预算定额居于中央：它是确定一定计量单位分项工程或构件的人工、材料、机械台班消耗量的数量标准，按社会必要劳动时间确定水平；建设单位按预算定额为工程提供必要的人力物力资金，施工单位在定额范围内保质保期完成施工任务，预算定额是编施工图预算的依据（P000313）。"),
(300, 300, "为什么改？",
 "为什么改？功绩与局限要分开记账。功绩一面：它给工程计价立过相对统一的标准和规范，特定历史阶段保住了工程质量、撑住了合理确定造价的基本盘（P000317）；优点还有易于操作（以标准工时和工序为基础，对工程项目细致分解计算，方法简单明了）与便于成本管控（细致的工时工序划分可做细致的分类成本管控）（P000318）。局限一面：过于强调统一，难以反映不同企业的技术、管理与资源配置差异，压制市场竞争机制的发挥；与国际通行造价管理模式脱节，不利我国建筑企业参与国际竞争（P000317）；更直白的两条是——只体现社会平均水平下的工艺流程，装不下新工艺新技术的优势；市场竞争机制无法充分发挥，个别企业成本出不来，约束企业自主报价，选不出优秀投标人（P000318）。取消因此被表述为“不可避免的市场选择”：它将促使造价更贴市场实际，激发企业创新活力与竞争力（P000317、P000318）。"),
(306, 306, "对从业者的直接行动含义",
 "对从业者的行动含义有三条：**第一，合同里写死调差条款**——人工费调整对象（省单价还是市场价）、调整方法、取费规则、风险幅度，一处含糊就是日后一处争议[来源: P000331, P000324]；**第二，盯住项目所在地人工费调整文件与信息价发布节奏**——执行已调文件的地区人工倒挂已大幅收窄，争议最重的恰是执行旧版计价依据又未约定调差的项目[来源: P000332]；**第三，理解定额低价的功能性**——它服务国有投资项目拦标价编制与审计、造价司法鉴定与纠纷裁决、概算指标与工期定额编制基础、发承包谈判锚点四个刚性场景，以牺牲单价真实性换取计价统一可控，再靠动态调整与价差找补机制补偿真实性损失（P000332）。"),
(309, 309, "过去，造价咨询机构",
 "过去，造价咨询机构与施工单位把政府预算定额当万能工具——编施工图预算、定限价、算结算、核成本全靠它（P000318、P000320）。可它本质是“量价合一”或绑定法定费率的社会平均消耗标准，装的是编制期绝大多数企业的平均技术、平均装备、平均工效（P000303、P000304），放进市场化竞价，根本性局限立刻显形："),
(324, 327, "3. **第三步：精准测定企业三要素消耗量指标**",
 "3. **第三步：三要素消耗量指标按3.1节口径精准测定**\n   人工按普工、一般技工、高级技工分类测基本用工、超运距用工与辅助用工，结合企业管理水平设定内部人工幅度差；材料按理论净用量叠加场内运输、操作、堆放三类损耗，定出优于社会平均水平的企业损耗率；机械按主机与配合辅助机械分测台班，2000元以内小型机具划入企业管理费（构成明细见3.1.1节）（P000302、P000303、P000315）。"),
(333, 337, "**企业定额为什么是市场化的接盘者。**",
 "**企业定额为什么是市场化的接盘者。**市场化计价这趟车，终点站是企业定额。施工定额、企业定额、预算定额三者的体系关系3.3.1节已列：企业定额是承包方按自身技术与管理水平编制、反映企业个别成本的内部定额，水平通常高于预算定额、低于施工定额（P000321）。市场人工价远高于定额价的现实，反过来正是企业定额的机会——用自测的消耗量（贴近本企业实际效率）配市场单价，报价才既有竞争力又不亏本。"),
(339, 339, "编制企业定额的方法并不神秘",
 "编制企业定额的方法并不神秘，3.1.3节的工具直接可用：以GB/T 23859—2025的秒表测时法与影像记录法测本企业典型工序的作业要素延续时间（P000354），以技术测定法定新项目和典型项目、统计分析法消化自家统计资料、比较类推法从典型子目推相邻子目、经验估计法补局部临时项目（P000356）——这正是“经验估计法一般仅适用于企业内部制定局部项目的补充定额”的正面用法。定额停发预期下咨询企业的转型也以数据能力为轴：积累多地区、多类型、多规模项目的人工材料机械价格数据并保持及时更新，建快速算量与灵活计价的工具体系，发展全过程造价咨询、造价司法鉴定、工程保险理赔咨询等特色服务，健全风险管理体系（P000317）。"),
]
